create table precision_numeric_def (big_decimal number(10,1), big_integer number(10,1), double_primitive binary_double, double_wrap binary_double, float_primitive binary_double, float_wrap binary_double, id number(19,0) not null, primary key (id));
create table precision_numeric_set (big_decimal number(38,2), big_integer number(38,0), double_primitive binary_double, double_wrap binary_double, float_primitive binary_float, float_wrap binary_float, id number(19,0) not null, primary key (id));
create table precision_time_def (local_date date, local_time timestamp(0), offset_time timestamp(0) with time zone, sql_date date, sql_time timestamp(0), dt_instant timestamp(9) with time zone, id number(19,0) not null, java_date timestamp(9), local_date_time timestamp(9), offset_date_time timestamp(9) with time zone, sql_timestamp timestamp(9), zoned_date_time timestamp(9) with time zone, primary key (id));
create table precision_time_set (local_date date, local_time timestamp(0), offset_time timestamp(0) with time zone, sql_date date, sql_time timestamp(0), dt_instant timestamp(9) with time zone, id number(19,0) not null, java_date timestamp(9), local_date_time timestamp(9), offset_date_time timestamp(9) with time zone, sql_timestamp timestamp(9), zoned_date_time timestamp(9) with time zone, primary key (id));
